/* eslint-disable react/require-default-props */
import React from 'react';
import {
  StyledGroup,
  StyledErrorMessage,
  ErrorIcon,
  StyledContainer,
  StyledRadioItem,
  StyledIndicator,
  StyledLabel,
} from './Radio.styles';
import { RadioProps, RadioItemProps } from './RadioTypes';

export const RadioGroup = ({
  error = false,
  errorMessage,
  children,
  css,
  ...props
}: RadioProps): JSX.Element => (
  <StyledGroup
    aria-invalid={error}
    aria-errormessage={error ? 'msgID' : undefined}
    error={error}
    css={css}
    {...props}
  >
    {children}
    {error && (
      <StyledErrorMessage id="msgID" aria-live="assertive">
        <ErrorIcon size="medium" aria-hidden />
        {errorMessage}
      </StyledErrorMessage>
    )}
  </StyledGroup>
);

export const RadioItem = React.forwardRef<React.ElementRef<typeof StyledRadioItem>, RadioItemProps>(
  ({ value, id, label, disabled = false, css, ...props }, forwardedRef): JSX.Element => (
    <StyledContainer css={css}>
      <StyledRadioItem ref={forwardedRef} value={value} id={id} disabled={disabled} {...props}>
        <StyledIndicator disabled={disabled} />
      </StyledRadioItem>
      <StyledLabel disabled={disabled} htmlFor={id}>
        {label}
      </StyledLabel>
    </StyledContainer>
  )
);
